const __aivicBundle_8_calculateMealPlanOptimizationScore = (() => {
  interface CalculateMealPlanOptimizationScoreResult {
    id: string;
    seasonalIngredientCount: number;
    totalDiscountRate: number;
    averageInventoryFulfillmentRate: number;
    optimizationScore: number;
  }
  
   function calculateMealPlanOptimizationScore(
    mealPlans: Array<{
      id: string;
      dishes: Array<{
        ingredientId: string;
        ingredientName: string;
        isSeasonalIngredient: boolean;
        discountRate: number;
        inventoryFulfillmentRate: number;
      }>;
    }>
  ): CalculateMealPlanOptimizationScoreResult[] {
    const scoredPlans = mealPlans.map((plan) => {
      const dishes = plan.dishes || [];
  
      // 旬の食材の数をカウント
      const seasonalIngredientCount = dishes.filter(
        (dish) => dish.isSeasonalIngredient === true
      ).length;
  
      // 割引率の合計を計算
      const totalDiscountRate = dishes.reduce(
        (sum, dish) => sum + (dish.discountRate || 0),
        0
      );
  
      // 在庫充足度の平均を計算
      const averageInventoryFulfillmentRate =
        dishes.length > 0
          ? dishes.reduce((sum, dish) => sum + (dish.inventoryFulfillmentRate || 0), 0) /
            dishes.length
          : 0;
  
      // 最適化スコアを計算
      // 旬の食材: 1件あたり10点
      // 割引率: 合計値をそのまま加算
      // 在庫充足度: 平均値をそのまま加算
      const optimizationScore =
        seasonalIngredientCount * 10 +
        totalDiscountRate +
        averageInventoryFulfillmentRate;
  
      return {
        id: plan.id,
        seasonalIngredientCount,
        totalDiscountRate,
        averageInventoryFulfillmentRate,
        optimizationScore,
      };
    });
  
    // スコアを降順でソート
    scoredPlans.sort(
      (a, b) => b.optimizationScore - a.optimizationScore
    );
  
    return scoredPlans;
  }
  return { calculateMealPlanOptimizationScore };
})();
